module benchmark/solution

-- Helper to generate a list of numbers from 'current' up to (but not including) 'limit'
func generateNumbers(current: int, limit: int) -> [int] {
  if current >= limit
  then []
  else Cons(current, generateNumbers(current + 1, limit))
}

-- Predicate to check if a number is a multiple of 3 or 5
func isMultipleOf3Or5(n: int) -> bool {
  (n % 3 == 0) || (n % 5 == 0)
}

-- Canonical filter implementation (keeps elements that satisfy the predicate)
func filter[a](pred: func(a) -> bool, xs: [a]) -> [a] {
  match xs {
    [] => [],
    Cons(x, rest) =>
      if pred(x)
      then Cons(x, filter(pred, rest))
      else filter(pred, rest)
  }
}

-- Canonical fold (left fold) implementation (reduces a list to a single value)
func foldl[a, b](f: func(b, a) -> b, acc: b, xs: [a]) -> b {
  match xs {
    [] => acc,
    Cons(x, rest) => foldl(f, f(acc, x), rest)
  }
}

-- The main entry point for the program
export func main() -> () ! {IO} {
  let numbers = generateNumbers(1, 1000); -- Generate numbers from 1 to 999
  let multiples = filter(isMultipleOf3Or5, numbers); -- Filter for multiples of 3 or 5
  let add = func(a: int, b: int) -> int { a + b }; -- Function to add two integers
  let sum = foldl(add, 0, multiples); -- Sum the filtered numbers

  print(show(sum)) -- Print the final sum
}

