from typing import Annotated

class IOEffect:
    def __repr__(self) -> str:
        return "IO"

class FSEffect:
    def __repr__(self) -> str:
        return "FS"

def computeSum(a: int, b: int) -> int:
    """PURE: no side effects"""
    return a + b

def printSum(a: int, b: int) -> Annotated[None, IOEffect()]:
    """IO: prints to standard output"""
    s = computeSum(a, b)
    print(f"Sum: {s}")

def logToFile(filename: str, message: str) -> Annotated[None, IOEffect(), FSEffect()]:
    """IO + FS: writes message to a file"""
    with open(filename, "a", encoding="utf-8") as f:
        f.write(message + "\n")

def main() -> None:
    result = computeSum(10, 20)
    printSum(10, 20)
    logToFile("output.txt", f"Sum was {result}")
    print("Done")

if __name__ == "__main__":
    main()

