from typing import Generic, TypeVar, Union

T = TypeVar('T')

class Ok(Generic[T]):
    def __init__(self, value: T):
        self.value = value

    def is_ok(self) -> bool:
        return True

    def is_err(self) -> bool:
        return False

    def __repr__(self) -> str:
        return f"Ok({self.value!r})"

class Err:
    def __init__(self, message: str):
        self.message = message

    def is_ok(self) -> bool:
        return False

    def is_err(self) -> bool:
        return True

    def __repr__(self) -> str:
        return f"Err({self.message!r})"

Result = Union[Ok[T], Err]

def parse_int(s: str) -> Result[int]:
    try:
        n = int(s)
        return Ok(n)
    except ValueError:
        return Err("Invalid integer")

def divide_safe(a: int, b: int) -> Result[int]:
    if b == 0:
        return Err("Division by zero")
    else:
        return Ok(a // b)

# Test Case 1: parse_int("10") then divide by 2
initial_result_1 = parse_int("10")
if initial_result_1.is_ok():
    final_result_1 = divide_safe(initial_result_1.value, 2)
else:
    final_result_1 = initial_result_1

if final_result_1.is_ok():
    print(f"Result: {final_result_1.value}")
else:
