type Tree = Leaf(int) | Node(Tree, int, Tree)

export func tree_sum(t: Tree) -> int {
  match t {
    Leaf(v) => v,
    Node(l, v, r) => tree_sum(l) + v + tree_sum(r)
  }
}

export func find_max(t: Tree) -> int {
  match t {
    Leaf(v) => v,
    Node(Leaf(x), v, Leaf(y)) => {
      let m1 = if x >= y then x else y;
      if v >= m1 then v else m1
    },
    Node(Leaf(x), v, r) => {
      let rmax = find_max(r);
      let m1 = if x >= rmax then x else rmax;
      if v >= m1 then v else m1
    },
    Node(l, v, Leaf(y)) => {
      let lmax = find_max(l);
      let m1 = if lmax >= y then lmax else y;
      if v >= m1 then v else m1
    },
    Node(l, v, r) => {
      let lmax = find_max(l);
      let rmax = find_max(r);
      let m1 = if lmax >= rmax then lmax else rmax;
      if v >= m1 then v else m1
    }
  }
}

export func main() -> () ! {IO} {
  let tree = Node(Leaf(1), 5, Node(Leaf(3), 7, Leaf(2)));
  let s = tree_sum(tree);
  let m = find_max(tree);
  print("Sum: " ++ show(s));
  print("Max: " ++ show(m))
}

